  return {
    armor: s.armor,
    engine: s.engine,
    gun: s.gun,
    reload: s.reload,
    maxHp: 100 + 25 * s.armor,
    maxSpeed: 110 + 22 * s.engine,
    turnRate: 1.8 + 0.25 * s.engine,
    turretRate: TURRET_RATE,
    damage: 18 + 5 * s.gun,
