    jobs.push({ id: m, a: aDir, b: bDir, rounds: opt.rounds, jitter: opt.jitter, seed: opt.seed * 1000 + m, map: mapIdx, sa: opt.sa, sb: opt.sb, pa: opt.pa, pb: opt.pb, offset: opt.offset });
