  else if (k === '--sb') { opt.sb = parseStats(v); i++; } else if (k === '--limit') { opt.limit = +v; i++; }
  else if (k === '--spread') { opt.spread = +v; i++; } else if (k === '--seed') { opt.seed = +v; i++; }
}
