const fs = require('fs');
let s = fs.readFileSync('tank/bot.js', 'utf8');
const rep = (a, b) => { if (!s.includes(a)) throw new Error('not found: ' + a.slice(0, 80)); s = s.replace(a, b); };
// --- learning of sample weights ---
rep(`const MEM = { round: -1 };`, `const MEM = { round: -1, counts: null };

// Веса прогнозов движения врага: априори + статистика, какому прогнозу враг следовал после наших выстрелов.
function sampleWeights() {
  if (!MEM.counts) {
    MEM.counts = new Float64Array(10);
    for (let j = 0; j < 10; j++) MEM.counts[j] = P.priorN * (j === 0 ? P.wCont : (1 - P.wCont) / 9);
  }
  return MEM.counts;
}

function learnFromShots(state) {
  if (!RD.pending || !RD.pending.length || !state.enemy.alive) return;
  const e = state.enemy;
  const keep = [];
  for (const rec of RD.pending) {
    if (state.tick < rec.due) { keep.push(rec); continue; }
    if (state.tick > rec.due + 2) continue;
    const c = sampleWeights();
    let sum = 0;
    const wts = new Float64Array(10);
    for (let j = 0; j < 10; j++) {
      const dx = rec.xs[j] - e.x, dy = rec.ys[j] - e.y;
      wts[j] = Math.exp(-(dx * dx + dy * dy) / (2 * 18 * 18));
      sum += wts[j];
    }
    if (sum < 1e-6) continue; // враг сделал что-то вне модели
    let tot = 0;
    for (let j = 0; j < 10; j++) tot += c[j];
    const decay = tot > P.memN ? P.memN / tot : 1;
    for (let j = 0; j < 10; j++) c[j] = c[j] * decay + wts[j] / sum;
  }
  RD.pending = keep;
}`);
rep(`    smp.w = j === 0 ? P.wCont : (1 - P.wCont) / (E_ACT.length - 1);`, `    smp.w = W_TMP[j];`);
rep(`function predictEnemy(e, walls) {
  const st = e.stats;`, `const W_TMP = new Float64Array(10);
function predictEnemy(e, walls) {
  const st = e.stats;
  const c = sampleWeights();
  let tot = 0;
  for (let j = 0; j < 10; j++) tot += c[j];
  for (let j = 0; j < 10; j++) W_TMP[j] = c[j] / tot;`);
// record pending at fire
rep(`    if (!r.blocked && r.self < 0.02 && r.p >= P.fireMin) fire = true;`, `    if (!r.blocked && r.self < 0.02 && r.p >= P.fireMin) fire = true;
    if (fire) {
      // Запомнить, где был бы враг по каждому прогнозу в момент пролёта снаряда.
      const s0 = samples[0];
      let kc = N_AIM - 1;
      for (let k = 0; k < N_AIM; k++) {
        if (MUZ + vb * DT * (k + 1) >= Math.hypot(s0.x[k] - cx, s0.y[k] - cy)) { kc = k; break; }
      }
      if (kc < N_AIM - 1) {
        const xs = new Float64Array(10), ys = new Float64Array(10);
        for (let j = 0; j < 10; j++) { xs[j] = samples[j].x[kc]; ys[j] = samples[j].y[kc]; }
        (RD.pending || (RD.pending = [])).push({ due: ctx.state.tick + kc + 1, xs, ys });
      }
    }`);
rep(`  updateEstimate(enemy);`, `  updateEstimate(enemy);
  learnFromShots(state);`);
rep(`  wCont: 0.4,      // вес прогноза «враг продолжит как едет»`, `  wCont: 0.4,      // вес прогноза «враг продолжит как едет»
  priorN: 12,      // сила априорных весов прогнозов (в наблюдениях)
  memN: 80,        // память статистики прогнозов (в наблюдениях)
  endT: 25,        // за сколько секунд до конца включать режим «прятаться/атаковать» по доле HP`);
// --- endgame HP-aware mode ---
rep(`  // Зона скоро накроет — всё подчинено возвращению внутрь.`, `  // Концовка: при таймауте побеждает доля HP.
  ctx.endMode = null;
  if (enemy.alive && state.timeLeft < P.endT) {
    const fm = me.hp / me.maxHp, fe = enemy.hp / enemy.maxHp;
    if (fm > fe + 0.01) ctx.endMode = 'hide';
    else if (fm < fe - 0.01) ctx.endMode = 'attack';
  }
  if (ctx.endMode === 'attack') { pref = Math.min(myKill - 80, 260); minSafe = 0; }
  else if (ctx.endMode === 'hide') { pref = Math.max(pref, theirKill + 150); minSafe = Math.max(minSafe, theirKill + 40); }
  // Зона скоро накроет — всё подчинено возвращению внутрь.`);
rep(`          if (!segClear(gx, gy, enemy.x, enemy.y, 6, RD.walls)) sc += 220;`, `          const los = segClear(gx, gy, enemy.x, enemy.y, 6, RD.walls);
          if (ctx.endMode === 'hide') { if (los) sc += 260; }
          else if (!los) sc += 220;`);
