  w.onmessage = (e) => { const m = e.data; if (s.waiting) { const r = s.waiting; s.waiting = null; r(m); } else s.queue.push(m); };
  s.call = (msg, timeout) => new Promise((res) => {
    if (s.queue.length) { res(s.queue.shift()); return; }
    s.waiting = res;
    w.postMessage(msg);
    if (timeout) setTimeout(() => { if (s.waiting === res) { s.waiting = null; res(null); } }, timeout);
  });
  return s;
}
